// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(c) && caller != address(this));
        // Setup: ensure value > 0 and <= totalRemaining by dealing ETH to trigger getTokens
        uint256 totalRemaining = c.totalRemaining();
        uint256 value = c.value();
        // If value is 0 or > totalRemaining, the requirement fails; skip those cases
        vm.assume(value > 0 && value <= totalRemaining);
        // The caller is not blacklisted initially
        vm.assume(!c.blacklist(caller));
        // Call XBornID() which sets owner balances, then call receive to trigger getTokens
        c.XBornID();
        // Prank caller to send ETH to trigger receive() -> getTokens()
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 1 ether}("");
        // After the call, check that if getTokens succeeded and toGive > 0, caller is blacklisted
        if (success) {
            assertTrue(c.blacklist(caller));
        } else {
            // If the call reverted, the blacklist remains unchanged (false)
            assertTrue(!c.blacklist(caller));
        }
    }
}

